import { Hono } from "hono";

// Env is generated by `npm run types` (wrangler types) once deployed keys exist.
interface Env {
  MEDIA: R2Bucket;
  SCOUT_ORDER: string;
  GROUND_ORDER: string;
  AI_GATEWAY_ID: string;
  META_API_KEY?: string;
  ECHO_APP_TOKEN?: string;
}

export const app = new Hono<{ Bindings: Env }>();

app.get("/v1/health", (c) => {
  return c.json({
    ok: true,
    version: "0.1.0",
    metaKeyConfigured: Boolean(c.env?.META_API_KEY),
  });
});

export default {
  fetch: app.fetch,
};
